// AUDIO — usa SO o bloco [[AUDIO]]...[[/AUDIO]] do agente (fala distinta do texto)
const cur = $('Itera1').first().json;
const full = ((($('Callima').first() || {}).json || {}).output || '').toString();
const isLast = cur.is_last === true;
const m = full.match(/\[\[AUDIO\]\]([\s\S]*?)\[\[\/AUDIO\]\]/i);
function limpa(t){ return String(t).replace(/[*_#`~]/g,'').replace(/R\$\s?(\d+)/g,'$1 reais').replace(/\bR\$\b/g,'reais').replace(/\n{2,}/g,'. ').replace(/\s{2,}/g,' ').trim(); }
const tem = !!(m && m[1] && m[1].trim());
const usar = isLast && tem;
const _t = usar ? limpa(m[1]) : null;
return [{ json: { ...cur, usar_audio: usar, audio_text: _t, TEXT: _t, INSTANCE: cur.instance, NUMERO_LEAD: cur.remoteJid } }];

// QUEBRA — Callima template v6 (lê output do agente; tira [[AUDIO]]/[[LEAD]]; markdown WhatsApp; fallback)
const MAX_CHARS = 280;
const _d = $('Dados').first().json;
const INST=_d.INSTANCIA, JID=_d.NUMERO_LEAD;
let raw='';
try { raw = ((($('Callima').first()||{}).json)||{}).output || ''; } catch(e){ raw=''; }
function wpp(t){
  return String(t)
    .replace(/\[\[AUDIO\]\][\s\S]*?\[\[\/AUDIO\]\]/gi,'')
    .replace(/\[\[LEAD\]\][\s\S]*?\[\[\/LEAD\]\]/gi,'')
    .replace(/\[\[AGENDAR\]\][\s\S]*?\[\[\/AGENDAR\]\]/gi,'')
    .replace(/\*\*(.+?)\*\*/g,'*$1*').replace(/__(.+?)__/g,'_$1_')
    .replace(/^#{1,6}\s*/gm,'').trim();
}
const text = wpp(raw);
const out=[];
if(text){
  let blocos=[];
  const pp=text.split(/\n{2,}/).map(b=>b.trim()).filter(Boolean);
  if(pp.length>1){blocos=pp;}
  else if(text.length>MAX_CHARS){
    const sb=text.split(/(?<=[.!?])\s+(?=[A-ZÁÉÍÓÚÂÊÔÃÕÇ])/);
    let c=''; for(const s of sb){ if((c+' '+s).trim().length>MAX_CHARS&&c.length>0){blocos.push(c.trim());c=s;}else{c=c?c+' '+s:s;} } if(c.trim())blocos.push(c.trim());
  } else { blocos=[text]; }
  const fin=[];
  for(const b of blocos){ if(b.length<=MAX_CHARS){fin.push(b);} else { let r=b; while(r.length>MAX_CHARS){let x=r.lastIndexOf(' ',MAX_CHARS); if(x<MAX_CHARS*0.5)x=MAX_CHARS; fin.push(r.slice(0,x).trim()); r=r.slice(x).trim();} if(r)fin.push(r);} }
  for(let i=0;i<fin.length;i++){
    const pal=fin[i].split(' ').length; const base=Math.min(Math.max(pal*0.9,1500),9000);
    out.push({json:{message:fin[i],sequence_index:i,total_messages:fin.length,is_last:i===fin.length-1,instance:INST,remoteJid:JID,typing_delay:Math.floor(base+Math.floor(Math.random()*800))}});
  }
}
if(out.length===0){
  out.push({json:{message:'Oi! Acho que me perdi aqui 😅 pode me dizer de novo, por favor?',sequence_index:0,total_messages:1,is_last:true,instance:INST,remoteJid:JID,typing_delay:1500}});
}
return out;

const l = ($('Get Lead').first() || {json:{}}).json || {};
