if(l.necessidade) known.push('necessidade='+l.necessidade);
const ctx = known.length
  ? '[LEAD CONHECIDO â€” jÃ¡ sabemos estes dados, NÃƒO pergunte de novo; cumprimente pelo nome: '+known.join('; ')+']'
  : '[LEAD NOVO â€” ainda nÃ£o sabemos nome/empresa/necessidade; descubra com leveza, UMA pergunta por vez.]';
return [{ json: { input: ctx + '\n\nMensagem do cliente: ' + msg } }];

const full = ((($('Callima').first()||{}).json||{}).output||'').toString();
const phone = $('Dados').first().json.NUMERO_LEAD;
const esc = s => String(s||'').replace(/'/g, "''").trim();
let nome='',empresa='',necessidade='';
const m = full.match(/\[\[LEAD\]\]([\s\S]*?)\[\[\/LEAD\]\]/i);
if(m){ const b=m[1]; const g=(k)=>{const r=b.match(new RegExp(k+'\\s*[=:]\\s*([^;\\n]+)','i')); return r?r[1].trim():'';};
  nome=g('nome'); empresa=g('empresa'); necessidade=g('necessidade'); }
return [{ json: { phone:esc(phone), nome:esc(nome), empresa:esc(empresa), necessidade:esc(necessidade) } }];

const full = ((($('Callima').first()||{}).json||{}).output||'').toString();
const i = full.indexOf('[[AGENDAR]]'); const j = full.indexOf('[[/AGENDAR]]');
if(i<0||j<0||j<i) return [];
const b = full.slice(i+11, j);
const get=(k)=>{ for(const part of b.split(';')){ const idx=part.indexOf('='); if(idx>0 && part.slice(0,idx).trim().toLowerCase()===k){ return part.slice(idx+1).trim(); } } return ''; };
const inicio=get('inicio'), fim=get('fim'); let titulo=get('titulo')||'Compromisso';
if(!inicio||!fim) return [];
const phone=$('Dados').first().json.NUMERO_LEAD;
return [{ json:{ inicio, fim, titulo, phone } }];

const ev=$json||{};
const p=($('Parse Agendar').first()||{json:{}}).json||{};
const id=ev.id||''; const link=ev.htmlLink||'';
const s=(ev.start&&(ev.start.dateTime||ev.start.date))||p.inicio||'';
const e=(ev.end&&(ev.end.dateTime||ev.end.date))||p.fim||'';
const ok=!!id; let hh='';
try{ const d=new Date(s); if(!isNaN(d.getTime())) hh=d.toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}); }catch(_){}
const tit=p.titulo||'compromisso';
const msg= ok ? ('Pronto! Agendei: '+tit+(hh?(' \u2014 '+hh):'')+'. Qualquer coisa me avisa! \u2705') : ('Nao consegui concluir o agendamento agora \ud83d\ude15 vou encaminhar pro nosso time confirmar o horario pra voce.');
const _d=$('Dados').first().json;
return [{ json:{ ok, message:msg, phone:p.phone||'', titulo:tit, inicio:s, fim:e, externalRef:id, htmlLink:link, INSTANCIA:_d.INSTANCIA, NUMERO_LEAD:_d.NUMERO_LEAD } }];

return [
